  const rl=info?.rateLimit||{},sum=o=>Object.values(o||{}).reduce((a,p)=>({inputTokens:a.inputTokens+p.inputTokens,outputTokens:a.outputTokens+p.outputTokens,cacheTokens:a.cacheTokens+p.cacheTokens,costUsd:a.costUsd+p.costUsd}),{inputTokens:0,outputTokens:0,cacheTokens:0,costUsd:0});
